svg.script:
(function () {
  var svg = document.documentElement;

  // --- Step data: titles + bilingual bodies ---
  var TITLES = [
    { en: 'Create ticket' },
    { en: 'Verify + classify' },
    { en: '/route' },
    { en: 'Run pipeline → PR' },
    { en: '/code-review' },
    { en: 'Filter AI review' },
    { en: 'Human reviewer approve' },
    { en: 'QA verify' }
  ];
  var STEPS = [
    { num: '1',   tag: 'pm',      en: 'Creates the ticket in Linear with PRD, requirements, acceptance criteria.' },
    { num: '2 ★', tag: 'human',   en: 'Verify the ticket, fill gaps, and attach a classification label (<code>bug</code> / <code>port</code> / <code>feature</code>).' },
    { num: '3',   tag: 'auto',    en: '<code>/ggx-dispatcher</code> picks up the ticket and runs <code>/route</code>: reads the label and picks one pipeline lane.' },
    { num: '4',   tag: 'auto',    en: 'route runs one lane: <strong>port</strong> → <code>/port:ff</code> → ★<code>/spec-review</code> → <code>/dev:ff</code>; <strong>feature</strong> → <code>/dev:ff</code>; <strong>bug</strong> → <code>/bug:ff</code>. All converge into one PR.' },
    { num: '5',   tag: 'routine', en: 'At 03:00 HKT daily, <code>/code-review</code> runs and posts findings back as PR comments.' },
    { num: '6 ★', tag: 'human',   en: 'Filter the AI review comments, pick real issues, fix the code, push new commits.' },
    { num: '7 ★', tag: 'human',   en: 'Human reviewer reads the PR, comments, approves; on approval the PR is ✓ merged. Architecture / product judgment is gated here.' },
    { num: '8',   tag: 'qa',      en: 'QA runs verification on staging / prod and moves the ticket to Done on pass. The last gate at the feature level.' }
  ];
  // Per-step SVG focus: step node(s) + incoming arrow(s). Indexed 0-8 (tour step 1-9).
  var FOCUS = [
    ['.ov-step.s1'],
    ['.ov-step.s2'],
    ['.ov-step.s3'],
    ['.s-entry', '.s-spec'],
    ['.ov-step.s6'],
    ['.ov-step.s7'],
    ['.ov-step.s8'],
    ['.ov-step.s9']
  ];
  var ARROWS = [
    [],
    ['.ov-arrow.a1'],
    ['.ov-arrow.a2'],
    ['.ov-arrow.af1', '.ov-arrow.af2', '.ov-arrow.af3', '.ov-arrow.as1', '.ov-arrow.sd1'],
    ['.ov-arrow.cv1', '.ov-arrow.cv2'],
    ['.ov-arrow.a6'],
    ['.ov-arrow.a7'],
    ['.ov-arrow.a8']
  ];
  var TAG_LABELS = { pm: 'PM', human: 'HUMAN', auto: 'AUTO', routine: 'ROUTINE', qa: 'QA' };

  // --- Reveal animation ---
  function reveal() {
    svg.classList.remove('is-revealed');
    void svg.getBoundingClientRect();
    requestAnimationFrame(function () { svg.classList.add('is-revealed'); });
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function () { setTimeout(reveal, 60); });
  } else {
    setTimeout(reveal, 60);
  }

  // --- Language detection · prefer parent body[data-lang] when same-origin ---
  function currentLang() {
    return 'en'; /* images are English-only */
  }
  function applyLang(lang) {
    svg.setAttribute('data-lang', lang === 'en' ? 'en' : 'zh');
    if (active) render();
  }

  // --- Tour state ---
  var popup     = svg.querySelector('[data-tour-popup]');
  var stepEl    = svg.querySelector('[data-tour-step]');
  var tagEl     = svg.querySelector('[data-tour-tag]');
  var titleEl   = svg.querySelector('[data-tour-title]');
  var bodyEl    = svg.querySelector('[data-tour-body]');
  var dotsEl    = svg.querySelector('[data-tour-dots]');
  var prevBtn   = svg.querySelector('[data-tour-prev]');
  var nextBtn   = svg.querySelector('[data-tour-next]');
  var closeBtn  = svg.querySelector('[data-tour-close]');
  var startBtn  = svg.querySelector('[data-svg-tour]');
  var replayBtn = svg.querySelector('[data-svg-replay]');
  var backdrop  = svg.querySelector('.ov-tour-backdrop');
  var idx = 0;
  var active = false;

  // Build dots
  if (dotsEl) {
    for (var i = 0; i < STEPS.length; i++) {
      (function (n) {
        var d = document.createElementNS('http://www.w3.org/1999/xhtml', 'button');
        d.setAttribute('type', 'button');
        d.setAttribute('class', 'ov-tour-dot');
        d.setAttribute('aria-label', 'Jump to step ' + (n+1));
        d.addEventListener('click', function () { goTo(n); });
        dotsEl.appendChild(d);
      })(i);
    }
  }

  function render() {
    if (!popup) return;
    var s = STEPS[idx];
    var lang = currentLang();
    var title = (TITLES[idx] || {})[lang] || '';
    stepEl.textContent = 'Step ' + (idx + 1) + ' / ' + STEPS.length + ' · ' + s.num;
    tagEl.setAttribute('class', 'ov-tour-tag ' + s.tag);
    tagEl.textContent = TAG_LABELS[s.tag] || s.tag.toUpperCase();
    titleEl.textContent = title;
    bodyEl.innerHTML = s[lang] || s.zh || '';
    prevBtn.disabled = idx === 0;
    nextBtn.disabled = idx === STEPS.length - 1;
    // dots
    var dotChildren = dotsEl.children;
    for (var i = 0; i < dotChildren.length; i++) {
      if (i === idx) dotChildren[i].classList.add('active');
      else dotChildren[i].classList.remove('active');
    }
    // SVG focus — step node(s) + incoming arrow(s) per FOCUS / ARROWS maps
    var prev = svg.querySelectorAll('.tour-focus');
    for (var j = 0; j < prev.length; j++) prev[j].classList.remove('tour-focus');
    var sel = (FOCUS[idx] || []).concat(ARROWS[idx] || []);
    for (var k = 0; k < sel.length; k++) {
      var nodes = svg.querySelectorAll(sel[k]);
      for (var m = 0; m < nodes.length; m++) nodes[m].classList.add('tour-focus');
    }
  }

  function open() {
    if (!popup) return;
    active = true;
    idx = 0;
    svg.classList.add('tour-active');
    popup.removeAttribute('hidden');
    render();
  }
  function close() {
    if (!popup) return;
    active = false;
    svg.classList.remove('tour-active');
    var prev = svg.querySelectorAll('.tour-focus');
    for (var i = 0; i < prev.length; i++) prev[i].classList.remove('tour-focus');
    popup.setAttribute('hidden', 'hidden');
  }
  function goTo(n) {
    if (!active) return;
    if (n < 0 || n >= STEPS.length) return;
    idx = n;
    render();
  }
  function next() { goTo(idx + 1); }
  function prev() { goTo(idx - 1); }

  if (startBtn)  startBtn.addEventListener('click', function (e) { e.preventDefault(); open(); });
  if (closeBtn)  closeBtn.addEventListener('click', close);
  if (prevBtn)   prevBtn.addEventListener('click', prev);
  if (nextBtn)   nextBtn.addEventListener('click', next);
  if (replayBtn) replayBtn.addEventListener('click', function (e) { e.preventDefault(); reveal(); });
  if (backdrop)  backdrop.addEventListener('click', close);

  document.addEventListener('keydown', function (e) {
    if (!active) return;
    if (e.key === 'ArrowRight' || e.key === 'PageDown') { e.preventDefault(); next(); }
    else if (e.key === 'ArrowLeft' || e.key === 'PageUp') { e.preventDefault(); prev(); }
    else if (e.key === 'Escape') { e.preventDefault(); close(); }
  });

  // --- Host-driven messages ---
  window.addEventListener('message', function (e) {
    if (!e || !e.data) return;
    if (e.data.type === 'e2e-replay') reveal();
    else if (e.data.type === 'e2e-tour-open') open();
    else if (e.data.type === 'e2e-tour-close') close();
    else if (e.data.type === 'e2e-lang' && e.data.lang) applyLang(e.data.lang);
  });
  // --- Custom events (same-origin only) ---
  svg.addEventListener('e2e-replay',     function () { reveal(); });
  svg.addEventListener('e2e-tour-open',  function () { open(); });
  svg.addEventListener('e2e-tour-close', function () { close(); });

  // Initial language sync with host
  applyLang(currentLang());
})();
